styles.css:
/* ==========================================================================
   Clara Novak, personal graphic design portfolio. Paper, ink, one signal red.
   Gallery first: core Gallery blocks with the WordPress lightbox.
   ========================================================================== */
@font-face{font-family:"Familjen Grotesk";src:url({{kit-fonts}}/familjen-grotesk-var.woff2) format("woff2");font-weight:400 700;font-style:normal;font-display:swap}
@font-face{font-family:"Familjen Grotesk";src:url({{kit-fonts}}/familjen-grotesk-italic-var.woff2) format("woff2");font-weight:400 700;font-style:italic;font-display:swap}
@font-face{font-family:"Fragment Mono";src:url({{kit-fonts}}/fragment-mono-400.woff2) format("woff2");font-weight:400;font-style:normal;font-display:swap}

:root{
  --df-paper:#FBFBF9;--df-ink:#111;--df-mute:#5C5C58;--df-line:#E3E2DD;--df-wash:#F1F0EC;
  --df-red:#D42A12;--df-blush:#FBE6E1;--df-coral:#FF7A5C;
  --df-sans:"Familjen Grotesk","Helvetica Neue",Arial,sans-serif;
  --df-mono:"Fragment Mono",ui-monospace,Menlo,monospace;
  --df-pad:clamp(20px,4vw,64px);
  --df-gap:clamp(14px,1.8vw,28px);
  --df-sec:clamp(72px,9vw,144px);
  --df-r:14px;
  --df-ease:cubic-bezier(.2,.7,.2,1);
}
html{scroll-behavior:smooth;scroll-padding-top:84px}
body{background:var(--df-paper);color:var(--df-ink);font-family:var(--df-sans);-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;overflow-x:clip}
body :is(h1,h2,h3,h4){font-family:var(--df-sans);color:inherit;text-wrap:balance}
body p{text-wrap:pretty}
body a{color:inherit;text-decoration:none}
::selection{background:var(--df-red);color:#fff}

/* resets against the theme ------------------------------------------------ */
body main .wp-block-group{border-radius:0}
:where(body main) p,:where(body main) :is(h1,h2,h3,h4),:where(body main) figure,:where(body main) ul,:where(body main) ol,:where(body main) dl,:where(body main) dd,:where(body main) blockquote{margin:0}
:where(body main) .wp-block-group>*{margin-block:0}
:where(body main) :is(ul,ol){padding:0;list-style:none}
body main,body .wp-site-blocks{padding:0;margin:0}
body .wp-site-blocks>*{margin-block:0}
body main>.entry-content,body main .wp-block-post-content{margin:0;padding:0}
body main .wp-block-post-content>.df-sec{max-width:none;margin-inline:0;width:100%}
body .wp-block-image{margin:0}
body .wp-block-image img{display:block;width:100%;height:auto}

/* primitives -------------------------------------------------------------- */
.df-wrap{max-width:1360px;margin-inline:auto;padding-inline:var(--df-pad);box-sizing:content-box}
.df-sec{padding-block:var(--df-sec)}
.df-eyebrow{font-family:var(--df-mono);font-size:.78rem;line-height:1.5;letter-spacing:.04em;color:var(--df-mute)}
body .df-h1{font-size:clamp(2.35rem,4.9vw,4.6rem);font-weight:500;letter-spacing:-.035em;line-height:1.02}
body .df-h1 em{font-style:italic;font-weight:500;color:var(--df-red)}
body .df-h2{font-size:clamp(1.75rem,3vw,2.75rem);font-weight:500;letter-spacing:-.03em;line-height:1.06}
.df-lead{font-size:clamp(1.06rem,1.25vw,1.22rem);line-height:1.55;color:var(--df-mute);max-width:36em}
.df-arr{display:inline-block;transition:transform .35s var(--df-ease)}
a:hover .df-arr{transform:translateX(5px)}
.df-status{display:inline-flex;align-items:center;gap:.6em;font-size:.88rem;font-weight:500;line-height:1.2;color:var(--df-ink)}
.df-status::before{content:"";width:9px;height:9px;border-radius:50%;background:var(--df-red);box-shadow:0 0 0 4px var(--df-blush);flex:none}

.df-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px 40px;flex-wrap:wrap;margin-bottom:clamp(32px,4vw,56px)}
.df-head__l{display:grid;gap:14px}

/* buttons ----------------------------------------------------------------- */
body .wp-block-buttons{gap:12px;align-items:center}
body .wp-block-button__link{transition:background .25s,color .25s,border-color .25s;line-height:1.1;display:inline-flex;gap:.6em;align-items:center}
body .wp-block-button.df-btn-line .wp-block-button__link{background:transparent;color:var(--df-ink);border-color:var(--df-ink)}
body .wp-block-button.df-btn-line .wp-block-button__link:hover{background:var(--df-ink);color:#fff}
body .wp-block-button.df-link .wp-block-button__link{background:none;color:var(--df-ink);border:0;border-radius:0;padding:0 0 4px;box-shadow:inset 0 -1px 0 currentColor;font-weight:600}
body .wp-block-button.df-link .wp-block-button__link:hover{background:none;color:var(--df-red)}

/* header ------------------------------------------------------------------ */
body header.wp-block-template-part{position:sticky;top:0;z-index:50;background:none;border:0;padding:0;margin:0;box-shadow:none}
body header.wp-block-template-part::before{content:"";position:absolute;inset:0;z-index:-1;background:rgba(251,251,249,.9);backdrop-filter:saturate(1.2) blur(14px);-webkit-backdrop-filter:saturate(1.2) blur(14px);border-bottom:1px solid var(--df-line)}
body .df-header{display:flex;align-items:center;gap:24px;height:72px;max-width:1360px;margin:0 auto;padding:0 var(--df-pad);box-sizing:content-box;background:none}
.df-header>*{margin:0!important}
body .df-header .df-nav{margin-left:auto!important}
.df-brand{display:inline-flex;align-items:center;gap:10px;font-weight:600;font-size:1.12rem;letter-spacing:-.02em;white-space:nowrap}
.df-brand__dot{width:12px;height:12px;border-radius:50%;background:var(--df-red);transition:transform .35s var(--df-ease)}
.df-brand:hover .df-brand__dot{transform:scale(1.35)}
.df-header__tag{font-family:var(--df-mono);font-size:.76rem;color:var(--df-mute);white-space:nowrap;margin-right:auto!important;padding-left:18px;border-left:1px solid var(--df-line)}
body .df-nav .wp-block-navigation__container{gap:clamp(20px,2.6vw,40px)}
body .df-nav.wp-block-navigation{color:var(--df-ink)}
body .df-nav .wp-block-navigation-item__content{color:var(--df-ink)!important;font-weight:500;font-size:1rem;padding:6px 0;position:relative}
body .df-nav .wp-block-navigation-item__content::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--df-red);transform:scaleX(0);transform-origin:left;transition:transform .35s var(--df-ease)}
body .df-nav .wp-block-navigation-item__content:hover::after,body .df-nav .current-menu-item>.wp-block-navigation-item__content::after{transform:scaleX(1)}
body .df-nav .wp-block-navigation__responsive-container-open,body .df-nav .wp-block-navigation__responsive-container-close{color:var(--df-ink);padding:8px;margin-right:-8px}
body .df-nav .wp-block-navigation__responsive-container.is-menu-open{padding:24px var(--df-pad);background:var(--df-paper);z-index:100}
body .df-nav .is-menu-open :is(.wp-block-navigation__responsive-close,.wp-block-navigation__responsive-dialog){max-width:none;width:100%;margin:0;padding-inline:0}
body .df-nav .is-menu-open .wp-block-navigation__responsive-container-content{padding:64px 0 0!important;align-items:stretch}
body .df-nav .is-menu-open .wp-block-navigation__container{gap:0;width:100%;align-items:stretch}
body .df-nav .is-menu-open .wp-block-navigation-item{border-bottom:1px solid var(--df-line);width:100%}
body .df-nav .is-menu-open .wp-block-navigation-item__content{font-size:2.4rem;font-weight:500;letter-spacing:-.03em;padding:16px 0;display:block;width:100%}
body .df-nav .is-menu-open .wp-block-navigation-item__content::after{display:none}
body .df-nav .is-menu-open .wp-block-navigation-item__content:hover{color:var(--df-red)}

/* hero -------------------------------------------------------------------- */
.df-hero{padding-block:clamp(56px,7vw,112px) 0}
.df-hero__grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));column-gap:var(--df-gap);align-items:center}
.df-hero__text{grid-column:1/9;display:grid;gap:clamp(18px,2vw,28px);justify-items:start}
.df-hero__lead{max-width:34em}
.df-hero__btns{margin-top:8px!important}
.df-hero__side{grid-column:9/13;display:grid;justify-items:center;gap:22px}
body .df-avatar{width:min(100%,340px);aspect-ratio:1;border-radius:50%;overflow:hidden;background:#ECEAE4;isolation:isolate}
body .df-avatar img{width:100%;height:100%;object-fit:cover;object-position:50% 30%;mix-blend-mode:multiply}
.df-hero__status{background:#fff;border:1px solid var(--df-line);border-radius:999px;padding:10px 16px 10px 14px}
.df-facts{box-sizing:border-box;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));column-gap:var(--df-gap);margin-top:clamp(56px,7vw,104px)!important;padding-top:22px;padding-bottom:22px;border-top:1px solid var(--df-ink)}
.df-facts>div{display:grid;gap:6px}
.df-facts dt{font-family:var(--df-mono);font-size:.74rem;letter-spacing:.04em;color:var(--df-mute)}
.df-facts dd{margin:0;font-size:1rem;font-weight:500;line-height:1.35}

/* clients ----------------------------------------------------------------- */
.df-clients{padding-block:clamp(40px,5vw,72px);border-block:1px solid var(--df-line)}
.df-clients__head{display:flex;justify-content:space-between;gap:16px 40px;flex-wrap:wrap;margin-bottom:clamp(24px,3vw,40px)}
.df-clients__note{color:var(--df-mute);font-size:.95rem;max-width:32em}
.df-logos{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(24px,3vw,44px) var(--df-gap);align-items:center}
.df-logos li{display:flex;align-items:center;justify-content:flex-start;color:#6F6F6A;transition:color .3s}
.df-logos li:hover{color:var(--df-ink)}
.df-logos svg{height:30px;width:auto;max-width:100%;overflow:visible}

/* galleries --------------------------------------------------------------- */
body .df-grid.wp-block-gallery.has-nested-images{gap:var(--df-gap);margin:0}
body .df-grid.wp-block-gallery.has-nested-images figure.wp-block-image:not(#individual-image){width:auto;margin:0;flex-direction:column;align-items:stretch;justify-content:flex-start;overflow:visible}
body .df-grid.wp-block-gallery.has-nested-images figure.wp-block-image img{border-radius:var(--df-r);transition:transform .5s var(--df-ease),box-shadow .5s var(--df-ease);background:var(--df-wash)}
body .df-grid.wp-block-gallery.has-nested-images figure.wp-block-image figcaption{position:static;background:none;color:var(--df-ink);text-shadow:none;max-height:none;overflow:visible;padding:12px 2px 0;margin:0;font-size:.92rem;line-height:1.35;text-align:left;flex:none;display:flex;gap:.5em;flex-wrap:wrap}
body .df-grid.wp-block-gallery.has-nested-images figure.wp-block-image figcaption::before{display:none}
.df-grid figcaption strong{font-weight:600;transition:color .25s}
.df-grid figcaption{color:var(--df-mute)!important}
.df-grid figcaption strong{color:var(--df-ink)}
.df-grid figure:hover figcaption strong{color:var(--df-red)}
.df-grid figure:hover img{transform:translateY(-4px);box-shadow:0 18px 36px -22px rgba(17,17,17,.45)}
/* The lightbox button sits over the image: keep it visible on hover/focus only. */
body .df-grid .lightbox-trigger{opacity:0;transition:opacity .25s;background:rgba(17,17,17,.72)}
body .df-grid figure:hover .lightbox-trigger,body .df-grid .lightbox-trigger:focus-visible{opacity:1}
body .df-grid .lightbox-trigger svg path,body .df-grid .lightbox-trigger svg{fill:#fff}

/* Feature grid (home): 3 columns, every 1st and 7th image of seven spans two. */
body .df-grid--feature.wp-block-gallery.has-nested-images{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));row-gap:clamp(28px,3vw,44px)}
body .df-grid--feature.wp-block-gallery.has-nested-images figure.wp-block-image:not(#individual-image){display:flex}
body .df-grid--feature figure.wp-block-image img{aspect-ratio:4/5;height:auto;object-fit:cover}
body .df-grid--feature figure.wp-block-image:is(:nth-child(7n+1),:nth-child(7n+7)){grid-column:span 2}
body .df-grid--feature figure.wp-block-image:is(:nth-child(7n+1),:nth-child(7n+7)) img{aspect-ratio:33/20}

/* Masonry (work page): true aspect ratios, column count from the block. */
body .df-grid--masonry.wp-block-gallery.has-nested-images{display:block;column-count:3;column-gap:var(--df-gap)}
body .df-grid--masonry.wp-block-gallery.has-nested-images.columns-2{column-count:2}
body .df-grid--masonry.wp-block-gallery.has-nested-images.columns-4{column-count:4}
body .df-grid--masonry.wp-block-gallery.has-nested-images figure.wp-block-image:not(#individual-image){display:flex;break-inside:avoid;margin:0 0 clamp(26px,2.8vw,40px)}
body .df-grid--masonry figure.wp-block-image img{height:auto;object-fit:contain}

.df-gallery--home{padding-bottom:calc(var(--df-sec) * .8)}

/* page header + category chips ------------------------------------------- */
.df-phead{padding-bottom:clamp(24px,3vw,48px)}
.df-phead .df-wrap{display:grid;gap:20px;justify-items:start}
.df-phead__h{max-width:16em}
.df-chips ul{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
.df-chips a{display:inline-flex;align-items:center;gap:10px;border:1px solid var(--df-line);background:#fff;border-radius:999px;padding:10px 16px;font-weight:500;transition:border-color .25s,color .25s}
.df-chips a span{font-family:var(--df-mono);font-size:.74rem;color:var(--df-mute)}
.df-chips a small{font-size:.78rem;color:var(--df-mute)}
.df-chips a:hover{border-color:var(--df-ink);color:var(--df-red)}
.df-set{padding-block:clamp(40px,5vw,80px)}
.df-set+.df-set{border-top:1px solid var(--df-line)}
.df-set__head{display:grid;grid-template-columns:72px minmax(0,1fr) minmax(0,1.2fr);gap:12px var(--df-gap);align-items:baseline;margin-bottom:clamp(24px,3vw,44px)}
.df-set__n{font-family:var(--df-mono);font-size:.8rem;color:var(--df-red)}
.df-set__d{color:var(--df-mute);max-width:34em}

/* services ---------------------------------------------------------------- */
.df-services{background:var(--df-wash)}
.df-services__grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--df-gap)}
.df-svc{display:grid;align-content:start;gap:12px;padding-top:20px;border-top:1px solid var(--df-ink)}
.df-svc__n{font-family:var(--df-mono);font-size:.78rem;color:#B8240E}
body .df-svc__t{font-size:1.32rem;font-weight:600;letter-spacing:-.02em}
.df-svc__b{color:var(--df-mute);font-size:.98rem;line-height:1.55}

/* experience -------------------------------------------------------------- */
.df-exp__grid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:clamp(32px,6vw,96px);align-items:start}
.df-exp__head{display:grid;gap:18px;justify-items:start;position:sticky;top:110px}
.df-exp__list{border-top:1px solid var(--df-ink)}
.df-exp__row{display:grid;grid-template-columns:110px minmax(0,1fr) minmax(0,1.25fr);gap:8px var(--df-gap);padding:24px 0;border-bottom:1px solid var(--df-line);transition:background .3s}
.df-exp__years{font-family:var(--df-mono);font-size:.82rem;color:var(--df-mute);padding-top:4px}
body .df-exp__role{font-size:1.18rem;font-weight:600;letter-spacing:-.015em;line-height:1.25}
.df-exp__org{color:var(--df-red);font-weight:500;font-size:.98rem;margin-top:2px!important}
.df-exp__desc{color:var(--df-mute);font-size:.98rem;line-height:1.55}
.df-awards{display:grid;gap:10px;margin-top:6px!important;font-size:.98rem}
.df-awards li{display:grid;grid-template-columns:52px 1fr;gap:10px}
.df-awards span{font-family:var(--df-mono);font-size:.8rem;color:var(--df-red);padding-top:3px}

/* testimonials ------------------------------------------------------------ */
body .df-quote{border:0;margin:0;padding:0;display:grid;gap:22px;background:none;border-radius:0;box-shadow:none}
body .df-quote p{font-size:1.12rem;line-height:1.55;font-style:normal}
body .df-quote cite{text-transform:none;letter-spacing:0;font-style:normal;font-size:.92rem;color:var(--df-mute);display:flex;flex-direction:column;gap:2px}
body .df-quote cite strong{color:var(--df-ink);font-weight:600;font-size:1rem}
.df-testimonial{padding-top:calc(var(--df-sec) * .6)}
body .df-quote--big{max-width:1000px;position:relative;padding-left:clamp(0px,7vw,110px)}
body .df-quote--big::before{content:"\201C";position:absolute;left:0;top:-.12em;font-size:clamp(5rem,10vw,9rem);line-height:1;color:var(--df-red);font-weight:600}
body .df-quote--big p{font-size:clamp(1.5rem,2.7vw,2.4rem);line-height:1.22;letter-spacing:-.025em;font-weight:500;color:var(--df-ink)}
@media (max-width:781px){body .df-quote--big::before{position:static;display:block;height:.5em;font-size:5rem}}
.df-quotes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--df-gap)}
.df-quotes .df-quote{background:#fff;border:1px solid var(--df-line);border-radius:var(--df-r);padding:clamp(24px,2.4vw,36px);align-content:space-between;transition:border-color .3s,transform .4s var(--df-ease)}
.df-quotes .df-quote:hover{border-color:var(--df-ink);transform:translateY(-3px)}
.df-quotes .df-quote p::before{content:"\201C";display:block;color:var(--df-red);font-size:2.6rem;line-height:.8;font-weight:600;margin-bottom:10px}

/* about ------------------------------------------------------------------- */
.df-about{padding-top:clamp(56px,7vw,112px)}
.df-about__grid{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:clamp(32px,6vw,96px);align-items:start}
.df-about__text{display:grid;gap:22px}
.df-about__text>p:not(.df-eyebrow):not(.df-lead){max-width:36em;line-height:1.65}
body .df-about__img{border-radius:var(--df-r);overflow:hidden;position:sticky;top:110px}
body .df-about__img{background:#ECEAE4;isolation:isolate}
body .df-about__img img{aspect-ratio:4/5;object-fit:cover;object-position:50% 25%;mix-blend-mode:multiply}
.df-principles{background:var(--df-wash)}
.df-principles__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--df-gap)}
.df-pr{display:grid;gap:12px;align-content:start;padding-top:20px;border-top:1px solid var(--df-ink)}
.df-pr__n{font-family:var(--df-mono);font-size:.78rem;color:#B8240E}
body .df-pr__t{font-size:1.32rem;font-weight:600;letter-spacing:-.02em}
.df-pr p:last-child{color:var(--df-mute)}

/* cta --------------------------------------------------------------------- */
.df-cta{padding-block:var(--df-sec)}
.df-sec+.df-cta{padding-top:0}
.df-cta .df-wrap>.df-cta__grid{background:var(--df-ink);color:#fff;border-radius:calc(var(--df-r) * 1.6);padding:clamp(32px,5vw,80px);display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:clamp(28px,4vw,64px);align-items:end}
.df-cta__text{display:grid;gap:20px;justify-items:start}
.df-cta .df-status{color:#fff}
.df-cta .df-status::before{background:var(--df-coral);box-shadow:0 0 0 4px rgba(255,122,92,.22)}
.df-cta .df-lead{color:#C9C9C4}
.df-cta__side{display:grid;gap:22px;justify-items:start}
.df-cta__mail{font-size:clamp(1.2rem,1.9vw,1.6rem);font-weight:500;letter-spacing:-.02em}
.df-cta__mail a{box-shadow:inset 0 -2px 0 var(--df-coral);transition:color .25s}
.df-cta__mail a:hover{color:var(--df-coral)}
body .df-cta .wp-block-button.df-btn .wp-block-button__link:hover{background:#fff;color:var(--df-ink);border-color:#fff}

/* social links ------------------------------------------------------------ */
body .wp-block-social-links.df-social{gap:8px;margin:0;padding:0;font-size:16px}
body .wp-block-social-links.df-social .wp-social-link{background:transparent!important;color:inherit!important;border:1px solid currentColor;border-radius:999px;transition:background .25s,color .25s,border-color .25s;font-size:.9rem}
body .wp-block-social-links.df-social .wp-social-link a{padding:9px 14px 9px 12px;color:inherit!important;gap:8px;align-items:center}
body .wp-block-social-links.df-social .wp-social-link svg{width:16px;height:16px}
body .wp-block-social-links.df-social .wp-block-social-link-label{font-weight:500;font-size:.88rem;line-height:1}
body .wp-block-social-links.df-social .wp-social-link:hover{transform:none;background:var(--df-red)!important;border-color:var(--df-red);color:#fff!important}
.df-contact .df-social{color:var(--df-ink)}
.df-cta .df-social{color:#fff}

/* contact ----------------------------------------------------------------- */
.df-contact{padding-top:clamp(56px,7vw,112px)}
.df-contact__grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(32px,6vw,96px);align-items:start}
.df-contact__info{display:grid;gap:22px;justify-items:start}
.df-contact__mail{font-size:clamp(1.3rem,2.2vw,1.9rem);font-weight:500;letter-spacing:-.02em}
.df-contact__mail a{box-shadow:inset 0 -2px 0 var(--df-red);transition:color .25s}
.df-contact__mail a:hover{color:var(--df-red)}
.df-cdl{display:grid;width:100%;border-top:1px solid var(--df-line)}
.df-cdl>div{display:grid;grid-template-columns:130px 1fr;gap:12px;padding:14px 0;border-bottom:1px solid var(--df-line)}
.df-cdl dt{font-family:var(--df-mono);font-size:.78rem;color:var(--df-mute);padding-top:3px}
.df-cdl dd{margin:0;font-weight:500}
.df-cdl a:hover{color:var(--df-red)}
.df-contact__form{position:sticky;top:110px}
.df-form{background:#fff;border:1px solid var(--df-line);border-radius:calc(var(--df-r) * 1.4);padding:clamp(24px,3vw,44px);display:grid;gap:18px}
.df-form__title{font-size:1.4rem;font-weight:600;letter-spacing:-.02em}
.df-form label{display:grid;gap:8px;font-size:.88rem;font-weight:600}
.df-form__row{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.df-form :is(input,select,textarea){font:inherit;font-weight:400;font-size:1rem;color:var(--df-ink);background:var(--df-paper);border:1px solid #CFCEC8;border-radius:10px;padding:13px 14px;width:100%;box-sizing:border-box;transition:border-color .2s,box-shadow .2s}
.df-form select{appearance:none;background-image:linear-gradient(45deg,transparent 50%,var(--df-ink) 50%),linear-gradient(135deg,var(--df-ink) 50%,transparent 50%);background-position:calc(100% - 20px) 55%,calc(100% - 15px) 55%;background-size:5px 5px;background-repeat:no-repeat;padding-right:40px}
.df-form textarea{resize:vertical;min-height:130px}
.df-form ::placeholder{color:#7A7A75}
.df-form :is(input,select,textarea):focus{outline:none;border-color:var(--df-ink);box-shadow:0 0 0 3px var(--df-blush)}
.df-form__foot{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-top:4px}
.df-form__btn{font:inherit;font-weight:600;font-size:1rem;background:var(--df-red);color:#fff;border:0;border-radius:999px;padding:15px 26px;cursor:pointer;display:inline-flex;gap:.6em;align-items:center;transition:background .25s}
.df-form__btn:hover{background:var(--df-ink)}
.df-form__foot p{font-size:.84rem;color:var(--df-mute)}
.df-faq{padding-top:0}
.df-faq__grid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:clamp(32px,6vw,96px);border-top:1px solid var(--df-ink);padding-top:clamp(32px,4vw,56px)}
.df-faq__head{display:grid;gap:14px;align-content:start}
body .df-qa{border-bottom:1px solid var(--df-line);padding:0}
body .df-qa summary{list-style:none;cursor:pointer;padding:20px 40px 20px 0;font-weight:600;font-size:1.1rem;position:relative}
body .df-qa summary::-webkit-details-marker{display:none}
body .df-qa summary::after{content:"+";position:absolute;right:4px;top:50%;transform:translateY(-50%);font-size:1.5rem;font-weight:400;color:var(--df-red);transition:transform .3s}
body .df-qa[open] summary::after{transform:translateY(-50%) rotate(45deg)}
body .df-qa p{color:var(--df-mute);padding:0 0 22px;max-width:40em}

/* footer ------------------------------------------------------------------ */
body footer.wp-block-template-part{margin:0;padding:0}
body .df-foot{background:var(--df-ink);color:#E8E8E4;padding:clamp(56px,6vw,88px) var(--df-pad) 28px;margin:0;max-width:none}
.df-foot>*{max-width:1360px;margin-inline:auto!important}
.df-foot__top{display:grid;grid-template-columns:minmax(0,1.6fr) repeat(3,minmax(0,1fr));gap:32px var(--df-gap);padding-bottom:clamp(40px,5vw,64px);border-bottom:1px solid #2E2E2C}
.df-foot__brand{display:grid;gap:12px;align-content:start}
.df-foot__name{font-size:1.8rem;font-weight:600;letter-spacing:-.03em;display:flex;align-items:center;gap:12px}
.df-foot__name::before{content:"";width:12px;height:12px;border-radius:50%;background:var(--df-coral)}
.df-foot__lede{color:#B5B5B0;max-width:24em;font-size:.98rem}
.df-foot__col{display:grid;gap:12px;align-content:start}
.df-foot__h{font-family:var(--df-mono);font-size:.76rem;color:#A3A39E;letter-spacing:.04em}
.df-foot__col p:not(.df-foot__h){line-height:1.9;font-size:.98rem}
.df-foot a{transition:color .25s}
.df-foot a:hover{color:var(--df-coral)}
.df-foot__base>*{margin:0!important}
.df-foot__base{display:flex;justify-content:space-between;gap:12px 24px;flex-wrap:wrap;padding-top:22px;font-size:.84rem;color:#A3A39E}

/* responsive -------------------------------------------------------------- */
@media (max-width:1100px){
  .df-logos{grid-template-columns:repeat(4,minmax(0,1fr))}
  .df-services__grid{grid-template-columns:repeat(2,minmax(0,1fr));row-gap:40px}
  .df-exp__row{grid-template-columns:96px minmax(0,1fr)}
  .df-exp__desc{grid-column:2}
  .df-foot__top{grid-template-columns:repeat(3,minmax(0,1fr))}
  .df-foot__brand{grid-column:1/-1}
}
@media (max-width:900px){
  .df-header__tag{display:none}
  .df-hero__grid{grid-template-columns:1fr;row-gap:28px}
  .df-hero__text{grid-column:1;order:2}
  .df-hero__side{grid-column:1;order:1;justify-items:start;grid-template-columns:auto 1fr;align-items:center;gap:18px;margin-bottom:28px}
  body .df-avatar{width:112px}
  .df-facts{grid-template-columns:repeat(2,minmax(0,1fr));row-gap:22px}
  .df-exp__grid,.df-about__grid,.df-contact__grid,.df-faq__grid{grid-template-columns:1fr}
  .df-exp__head,.df-about__img,.df-contact__form{position:static}
  body .df-about__img{max-width:520px}
  .df-quotes{grid-template-columns:1fr}
  .df-principles__grid{grid-template-columns:1fr;row-gap:32px}
  .df-cta .df-wrap>.df-cta__grid{grid-template-columns:1fr;align-items:start}
  .df-set__head{grid-template-columns:48px 1fr}
  .df-set__d{grid-column:2}
  body .df-grid--masonry.wp-block-gallery.has-nested-images,body .df-grid--masonry.wp-block-gallery.has-nested-images.columns-4{column-count:2}
}
@media (max-width:781px){
  body .df-header{height:62px}
  body .df-grid--feature.wp-block-gallery.has-nested-images{grid-template-columns:repeat(2,minmax(0,1fr))}
  body .df-grid--feature figure.wp-block-image:nth-child(7n+7){grid-column:auto}
  body .df-grid--feature figure.wp-block-image:nth-child(7n+7) img{aspect-ratio:4/5;height:auto}
  body .df-grid--feature figure.wp-block-image:nth-child(7n+1) img{aspect-ratio:3/2;height:auto}
  .df-logos{grid-template-columns:repeat(2,minmax(0,1fr))}
  .df-form__row{grid-template-columns:1fr}
  .df-foot__top{grid-template-columns:1fr 1fr}
}
@media (max-width:560px){
  .df-services__grid{grid-template-columns:1fr}
  .df-exp__row{grid-template-columns:1fr;gap:6px}
  .df-exp__desc{grid-column:1}
  .df-cdl>div{grid-template-columns:1fr;gap:4px}
  body .df-grid.wp-block-gallery.has-nested-images figure.wp-block-image figcaption{font-size:.84rem;flex-direction:column;gap:0}
  .df-foot__top>:nth-child(2){grid-column:1/-1}
  .df-foot__base{flex-direction:column}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  .df-grid figure img,.df-quotes .df-quote,.df-arr,.df-brand__dot{transition:none!important}
  .df-grid figure:hover img{transform:none}
}

body :focus:not(:focus-visible){outline:none!important}body :where(a,button,summary,[tabindex],[role=button],input[type=checkbox],input[type=radio],input[type=submit],input[type=button]):focus-visible{outline:2px solid #2563EB!important;outline-offset:3px!important;box-shadow:0 0 0 3px #fff}body :where(input,textarea,select):focus-visible{outline-color:#2563EB}.wp-block-navigation .wp-block-navigation-item__content:focus-visible{outline-offset:4px!important}
